body.script:
(function () {
    // ── Logo preview ─────────────────────────────────────────
    var logoFile = document.getElementById('logoFile');
    var logoImg  = document.getElementById('logoPreviewImg');
    var logoPh   = document.getElementById('logoPlaceholder');
    if (logoFile) {
        logoFile.addEventListener('change', function () {
            var f = this.files[0];
            if (!f) return;
            var rd = new FileReader();
            rd.onload = function (e) {
                logoImg.src = e.target.result;
                logoImg.style.display = 'block';
                logoPh.style.display  = 'none';
            };
            rd.readAsDataURL(f);
        });
    }

    // ── QR preview ───────────────────────────────────────────
    var qrFile = document.getElementById('qrFile');
    var qrImg  = document.getElementById('qrPreviewImg');
    var qrPh   = document.getElementById('qrPlaceholder');
    if (qrFile) {
        qrFile.addEventListener('change', function () {
            var f = this.files[0];
            if (!f) return;
            var rd = new FileReader();
            rd.onload = function (e) {
                qrImg.src = e.target.result;
                qrImg.style.display = 'block';
                qrPh.style.display  = 'none';
            };
            rd.readAsDataURL(f);
        });
    }

    // ── Poster preview ────────────────────────────────────────
    var posterFile = document.getElementById('posterFile');
    var posterPrev = document.getElementById('posterPreview');
    if (posterFile) {
        posterFile.addEventListener('change', function () {
            var f = this.files[0];
            if (!f) return;
            var rd = new FileReader();
            rd.onload = function (e) {
                posterPrev.src = e.target.result;
                posterPrev.style.display = 'block';
            };
            rd.readAsDataURL(f);
        });
    }

    // ── Theme card preview (static images) ───────────────────
    var previewImg = document.getElementById('themePreviewImg');
    var themeImages = {
        'vanilla':      '/auction_module/static/description/player_card_vanila.jpg',
        'butterscotch': '/auction_module/static/description/player_card_butterscotch.jpg',
        'strawberry':   '/auction_module/static/description/player_card_strawberry.jpg',
        'cherry':       '/auction_module/static/description/player_card_cherry.jpg',
        'pistah':       '/auction_module/static/description/player_card_pistah.jpg',
        'lemon':        '/auction_module/static/description/player_card_butterscotch.jpg',
    };

    document.querySelectorAll('input[name="player_display_template"]').forEach(function (r) {
        r.addEventListener('change', function () {
            if (previewImg && themeImages[this.value]) {
                previewImg.src = themeImages[this.value];
            }
        });
    });

    // ── Form submit: disable button to prevent double-submit ─
    var form = document.querySelector('form');
    var btn  = document.getElementById('submitBtn');
    if (form && btn) {
        form.addEventListener('submit', function () {
            btn.disabled = true;
            btn.textContent = 'Submitting\u2026';
        });
    }

    // ── Teams Modal ───────────────────────────────────────────
    var teamCountInput  = document.getElementById('teamCount');
    var teamRowsDiv     = document.getElementById('teamRows');
    var openBtn         = document.getElementById('openTeamsModal');
    var closeBtn        = document.getElementById('closeTeamsModal');
    var modal           = document.getElementById('teamsModal');
    var modalPane       = document.getElementById('modalTeamPane');
    var modalDots       = document.getElementById('modalDots');
    var modalCurrent    = document.getElementById('modalCurrent');
    var modalTotal      = document.getElementById('modalTotal');
    var prevBtn         = document.getElementById('modalPrev');
    var nextBtn         = document.getElementById('modalNext');
    var doneBtn         = document.getElementById('modalDone');
    var teamSummary     = document.getElementById('teamSummary');
    var teamChips       = document.getElementById('teamChips');

    var totalTeams = 0;
    var currentTeam = 1;
    // per-team logo preview data URLs (for display only)
    var logoDataUrls = {};

    function makeEl(tag, attrs, text) {
        var el = document.createElement(tag);
        if (attrs) Object.keys(attrs).forEach(function(k) { el.setAttribute(k, attrs[k]); });
        if (text !== undefined) el.textContent = text;
        return el;
    }

    /* Build the hidden form inputs for all teams (inside the form so they submit) */
    function buildHiddenTeamInputs(count) {
        teamRowsDiv.innerHTML = '';
        logoDataUrls = {};
        for (var i = 1; i <= count; i++) {
            var wrap = makeEl('div', {'data-team-index': String(i)});
            wrap.appendChild(makeEl('input', {type: 'text', name: 'team_name_' + i, id: 'team_name_' + i, value: ''}));
            wrap.appendChild(makeEl('input', {type: 'text', name: 'team_owner_' + i, id: 'team_owner_' + i, value: ''}));
            var fi = makeEl('input', {type: 'file', name: 'team_logo_' + i, id: 'team_logo_' + i, 'class': 'tr-file-hidden', accept: 'image/*'});
            wrap.appendChild(fi);
            teamRowsDiv.appendChild(wrap);
        }
    }

    /* Render the current team's pane inside the modal */
    function renderModalPane(idx) {
        var nameVal  = (document.getElementById('team_name_'  + idx) || {}).value || '';
        var ownerVal = (document.getElementById('team_owner_' + idx) || {}).value || '';
        var dataUrl  = logoDataUrls[idx] || '';

        modalPane.innerHTML = '';

        var card = makeEl('div', {'class': 'tr-modal-team-card'});

        // Team Name
        var ng = makeEl('div', {'class': 'tr-modal-field'});
        ng.appendChild(makeEl('label', {'class': 'tr-label', 'for': 'modal_team_name'}, 'Team Name'));
        var ni = makeEl('input', {type: 'text', id: 'modal_team_name', 'class': 'tr-input', placeholder: 'e.g. Royal Challengers', value: nameVal});
        ni.addEventListener('input', function() {
            var el = document.getElementById('team_name_' + currentTeam);
            if (el) el.value = this.value;
            updateSummaryChips();
        });
        ng.appendChild(ni);
        card.appendChild(ng);

        // Owner Name
        var og = makeEl('div', {'class': 'tr-modal-field'});
        og.appendChild(makeEl('label', {'class': 'tr-label', 'for': 'modal_team_owner'}, 'Owner Name'));
        var oi = makeEl('input', {type: 'text', id: 'modal_team_owner', 'class': 'tr-input', placeholder: 'e.g. Virat Kohli', value: ownerVal});
        oi.addEventListener('input', function() {
            var el = document.getElementById('team_owner_' + currentTeam);
            if (el) el.value = this.value;
        });
        og.appendChild(oi);
        card.appendChild(og);

        // Logo
        var lg = makeEl('div', {'class': 'tr-modal-field'});
        var ll = makeEl('label', {'class': 'tr-label'});
        ll.innerHTML = 'Team Logo \u00a0(Optional)';
        lg.appendChild(ll);

        var logoRow = makeEl('div', {style: 'display:flex;align-items:center;gap:16px;margin-top:6px;'});
        var previewBox = makeEl('div', {'class': 'tr-modal-logo-box'});
        var ph  = makeEl('span', {'class': 'tr-modal-logo-ph'}, '\uD83D\uDC65');
        var pim = makeEl('img', {'class': 'tr-modal-logo-img', src: dataUrl || '', alt: '', style: dataUrl ? '' : 'display:none;'});
        if (dataUrl) ph.style.display = 'none';
        previewBox.appendChild(ph);
        previewBox.appendChild(pim);

        var uploadWrap = makeEl('div');
        var uploadLbl  = makeEl('label', {'class': 'tr-upload-btn', 'for': 'modal_logo_input'}, '\u2B06 Upload Logo');
        var fileVis    = makeEl('input', {type: 'file', id: 'modal_logo_input', 'class': 'tr-file-hidden', accept: 'image/*'});

        fileVis.addEventListener('change', (function(teamIdx, imgEl, phEl) {
            return function() {
                var f = this.files[0];
                if (!f) return;
                // Copy file to the real hidden form input via DataTransfer
                try {
                    var dt = new DataTransfer();
                    dt.items.add(f);
                    var realInput = document.getElementById('team_logo_' + teamIdx);
                    if (realInput) realInput.files = dt.files;
                } catch(e) { /* DataTransfer not supported — file won't transfer but preview works */ }
                var rd = new FileReader();
                rd.onload = function(e) {
                    logoDataUrls[teamIdx] = e.target.result;
                    imgEl.src = e.target.result;
                    imgEl.style.display = 'block';
                    phEl.style.display  = 'none';
                };
                rd.readAsDataURL(f);
            };
        })(currentTeam, pim, ph));

        uploadWrap.appendChild(uploadLbl);
        uploadWrap.appendChild(fileVis);
        logoRow.appendChild(previewBox);
        logoRow.appendChild(uploadWrap);
        lg.appendChild(logoRow);
        card.appendChild(lg);

        modalPane.appendChild(card);

        // Update step indicators
        modalCurrent.textContent = idx;
        modalTotal.textContent   = totalTeams;
        updateDots(idx);
        prevBtn.disabled = idx === 1;
        nextBtn.disabled = idx === totalTeams;
    }

    function updateDots(active) {
        modalDots.innerHTML = '';
        var max = Math.min(totalTeams, 20);
        for (var i = 1; i <= max; i++) {
            var d = makeEl('span', {'class': 'tr-modal-dot' + (i === active ? ' active' : ''), 'data-idx': String(i)});
            (function(idx) {
                d.addEventListener('click', function() {
                    currentTeam = idx;
                    renderModalPane(idx);
                });
            })(i);
            modalDots.appendChild(d);
        }
        if (totalTeams > 20) {
            modalDots.appendChild(makeEl('span', {style: 'font-size:0.75rem;color:#94a3b8;'}, '+' + (totalTeams - 20) + ' more'));
        }
    }

    function updateSummaryChips() {
        teamChips.innerHTML = '';
        var anyFilled = false;
        for (var i = 1; i <= totalTeams; i++) {
            var el = document.getElementById('team_name_' + i);
            var nm = el ? el.value.trim() : '';
            var chip = makeEl('span', {'class': 'tr-team-chip' + (nm ? '' : ' tr-team-chip--empty')}, nm || 'Team ' + i);
            teamChips.appendChild(chip);
            if (nm) anyFilled = true;
        }
        teamSummary.style.display = totalTeams > 0 ? 'block' : 'none';
    }

    function openModal() {
        modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';
        currentTeam = 1;
        renderModalPane(currentTeam);
    }

    function closeModal() {
        modal.style.display = 'none';
        document.body.style.overflow = '';
        updateSummaryChips();
    }

    if (openBtn)  openBtn.addEventListener('click', openModal);
    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    if (doneBtn)  doneBtn.addEventListener('click', closeModal);

    if (prevBtn) prevBtn.addEventListener('click', function() {
        if (currentTeam > 1) { currentTeam--; renderModalPane(currentTeam); }
    });
    if (nextBtn) nextBtn.addEventListener('click', function() {
        if (currentTeam < totalTeams) { currentTeam++; renderModalPane(currentTeam); }
    });

    // Close on backdrop click
    if (modal) {
        modal.addEventListener('click', function(e) {
            if (e.target === modal) closeModal();
        });
    }

    // Keyboard: Escape closes, arrow keys navigate
    document.addEventListener('keydown', function(e) {
        if (modal && modal.style.display !== 'none') {
            if (e.key === 'Escape') closeModal();
            if (e.key === 'ArrowRight' && currentTeam < totalTeams) { currentTeam++; renderModalPane(currentTeam); }
            if (e.key === 'ArrowLeft'  && currentTeam > 1)           { currentTeam--; renderModalPane(currentTeam); }
        }
    });

    if (teamCountInput) {
        teamCountInput.addEventListener('input', function () {
            var n = parseInt(this.value, 10) || 0;
            if (n > 50) { this.value = 50; n = 50; }
            totalTeams = n;
            if (n > 0) {
                buildHiddenTeamInputs(n);
                openBtn.style.display = 'inline-flex';
                updateSummaryChips();
            } else {
                teamRowsDiv.innerHTML = '';
                openBtn.style.display = 'none';
                teamSummary.style.display = 'none';
            }
        });
    }
})();
